import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"title":"Changelog"},"headers":[],"relativePath":"about/changelog.md","filePath":"about/changelog.md"}'),o={name:"about/changelog.md"};function n(s,e,r,d,p,c){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">CHANGELOG <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;CHANGELOG&quot;">​</a></h1><h3 id="v1-0-2" tabindex="-1">v1.0.2 <a class="header-anchor" href="#v1-0-2" aria-label="Permalink to &quot;v1.0.2&quot;">​</a></h3><p><em>26/09/2026</em></p><ul><li><p>Major Feature: Life Editor Debugger for FlowPilot.</p></li><li><p>Update: New Doc site with new guides</p></li><li><p>Add: Editor Debugger. Pick a running instance (Debug Target), see each Task&#39;s live state (Running, Succeeded, Failed, Skipped) in the Tree View.</p></li><li><p>Add: Breakpoints on Tasks (F9 or click the row gutter). Play In Editor pauses when the Task starts, and the asset editor opens on it.</p></li><li><p>Add: Step (F10) to the next Task, Resume (F5), Pause and Stop from the FlowPilot editor toolbar and debug bar.</p></li><li><p>Add: Drag and drop Tasks from the Tasks Palette into the Tree View (before, after or into a Task, or onto empty space to add to the Root).</p></li><li><p>Add: In-Game Debug dropdown in the Level Editor toolbar and FlowPilot editor toolbar, to toggle the overlay and pick the FlowPilotComponent to display.</p></li><li><p>Add: Tree View toolbar (Add Task picker, Remove, Enable, Disable, Expand/Collapse All), richer context menu, F2 rename, double click to expand/rename, empty Flow hint.</p></li><li><p>Add: Tasks Palette search by display name, sorted categories with counts, Task icons, double click to add.</p></li><li><p>Update: New, pasted and duplicated Tasks go next to the selection (into a selected parent, after a selected Task) and are selected.</p></li><li><p>Update: Changing a Task class is undoable, keeps the name and the children when switching between parent Tasks (e.g: Sequence to Selector).</p></li><li><p>Update: In-game debug draws Loop and Sub Flow children, shows disabled Tasks, flow name/state in the components list and a message when the index is invalid.</p></li><li><p>Fix: Loop crashed (check) on its second iteration, and returned Error instead of Failed when its Task failed.</p></li><li><p>Fix: Sub Flow crashed when restarted (Reset after Exit), and dereferenced a null instance in Enter.</p></li><li><p>Fix: Play Sound / Play Sound 2D never reported as started (missing Super::Enter).</p></li><li><p>Fix: Actor cache kept growing when several Actors shared a GameplayTag, and skipped entries when removing stale ones.</p></li><li><p>Fix: Debug draw delegate leaked on every World (each PIE session).</p></li><li><p>Fix: Pasting Tasks could replace existing Tasks with the same name, and left orphan objects in the asset.</p></li></ul><h3 id="v1-0-1" tabindex="-1">v1.0.1 <a class="header-anchor" href="#v1-0-1" aria-label="Permalink to &quot;v1.0.1&quot;">​</a></h3><p><em>22/09/2026</em></p><ul><li>Fix: Couple of crashes</li><li>Add: Couple of tests</li><li>Add: Support for Unreal Engine 5.8</li><li>Add: Re-writes BP FadeScreen in Cpp.</li><li>Add: New Tasks: SetFocus, ClearFocus, MoveTo, RunBehavior AI tasks</li><li>Add: Viewport on Actor with FlowPilot Selected debug view</li></ul><h3 id="v0-9-3" tabindex="-1">v0.9.3 <a class="header-anchor" href="#v0-9-3" aria-label="Permalink to &quot;v0.9.3&quot;">​</a></h3><p><em>21/09/2024</em></p><p><strong>Breaking change:</strong></p><blockquote><p>Unimplemented Tick tasks no longer automatically succeed, allowing FlowPilotComponent to continue execution. FinishTask has to be called for the task to complete, or implement Tick and return manually.</p></blockquote><ul><li>Feature: Allows changing ticking group in Project Settings.</li><li>Add: Modal to confirm task deletion</li><li>Add: Automatic Documentation export to FlowPilot.dev</li><li>Add: Flow Pilot asset can be created from the Content Browser via the Gameplay Menu</li><li>Add: New Option to spawn Class at a specific world location/rotation</li><li>Fix: Rare crash when Task was selected without Outer Class.</li><li>Fix: Crash on Demo Map when you don&#39;t have a class to spawn, but still play the game. Gracefully Log and Exit instead of crash.</li><li>Fix: Parallel Task was not respecting disabled nodes.</li><li>Update: Set default spawn lifetime to persistent</li><li>Update: Move Defines to FlowPilotGlobals.h</li><li>Update: Remove Root Task and Children from details view. No longer needed as the Tree view works correctly.</li><li>Update: Demo Maps and basic TP Character to remove Dependencies.</li><li>Update: Default Root node is named after data asset now upon creation</li><li>Update: Change Delegates to dynamic multicast to allow subscribing via BP</li><li>Update: Simplify finishing of ongoing tasks by calling FinishTask.</li><li>Update: Rename UFPTask_FlowActorAsset to UFPTask_SubFlow to make it more akin to a group of FlowTasks. (aka SubTree)</li><li>Update: Remove UFPTaskRunner. Simplified method calls so that most of it is handled via UFPTask_Sequencer. UFPTask_Selector now inherits from UFPTask_Sequencer and swaps Success/Fail behavior</li></ul><h3 id="v0-9-2" tabindex="-1">v0.9.2 <a class="header-anchor" href="#v0-9-2" aria-label="Permalink to &quot;v0.9.2&quot;">​</a></h3><p><em>24/08/2024</em></p><ul><li>Add: New FPTask_PossessPawn, allowing pawn possession by Players or AI</li><li>Add: New FPTask_PlayAnimation. Similar to BTTask_PlayAnimation, but can play animation on multiple Pawns, and has Soft Pointer to Anim Asset.</li><li>Fix: Spawning new Classes at runtime with existing cached Tags will properly cache them as well.</li><li>Fix: Crash when pasting Task form one FlowPilotAsset to another</li><li>Fix: Some undo functionality has been restored</li><li>Fix: Properly removes null tasks when saving.</li><li>Add: Task Palette now has a search box to filter out the list of Tasks.</li><li>Update: Task Palette has Categories expanded by default now.</li><li>Update: Exposed method to grab Brushes directly from Tasks for customization</li></ul><h3 id="v0-9-1" tabindex="-1">v0.9.1 <a class="header-anchor" href="#v0-9-1" aria-label="Permalink to &quot;v0.9.1&quot;">​</a></h3><p><em>14/07/2024</em></p><ul><li>Fix: Task icons paths not showing up.</li><li>Del: Removes temporary icons for validation to prevent a crash</li></ul><h3 id="v0-9" tabindex="-1">v0.9 <a class="header-anchor" href="#v0-9" aria-label="Permalink to &quot;v0.9&quot;">​</a></h3><p><em>13/07/2024</em></p><ul><li>Add: Class Switcher in FlowPilotTask Customization View</li><li>Feature: Editor Task Palette Tab. You can now easily see tasks, grouped by category, and quickly add them to the flow.</li><li>Add: Show Quick Buttons Task is selected or hovered</li><li>Update: Only show toolbar when multiple tasks selected.</li><li>Add: Support for Unreal Engine 5.4</li></ul><h3 id="v0-8" tabindex="-1">v0.8 <a class="header-anchor" href="#v0-8" aria-label="Permalink to &quot;v0.8&quot;">​</a></h3><p><em>29/06/2014</em></p><ul><li>Update: Improve Error Logging</li><li>Add: New example content</li><li>Add: Customization and improves Debug View.</li><li>Add: FlowPilotEditor with Basic functionality</li><li>Add: Drag and Drop Support</li><li>Add: data validation to FlowPilotEditor</li><li>Add: Implemented Parent/Child relationship on <code>UFlowPilotTask</code></li><li>Refactor: Rename <code>UFPTaskNode</code> to <code>UFlowPilotTask</code></li><li>Add: missing ExitChildTask call from <code>UFPTask_Sequence</code> when a Task returns Failure</li><li>Add: Editor data to customize display of Tasks</li><li>Add: Editor Settings to customize editing experience</li><li>Fix: <code>UFPTaskRunner</code> was not correctly handling running the last Task if it was Disabled, returning Failure, instead of the last task result</li><li>Add: New FlowPilot Website and Online Documentation at <a href="http://flowpilot.dev" target="_blank" rel="noreferrer">http://flowpilot.dev</a></li><li>Deprecate: MainFlow in <code>UFlowPilot</code> in favor of <code>UFPTask_Sequence</code> as the root node</li><li>Add: Data Versioning to automatically convert MainFlow to Sequence Child Tasks</li><li>Add: Support for Unreal Engine 5.4</li><li>Fix: FlowPilot Control not properly setup for callbacks.</li><li>Refactor: Cancellation and Exit flow, it now normalized. All Successful and Failing tasks should call Exit Method</li><li>Adds: Exit method now has the task result passed as parameter</li><li>Adds: Validation to FlowActorReference</li><li>Adds: Validation to FlowPilotTasks that didn&#39;t have it</li><li>Fix: Bad usage of CPU Traces. Added others and CPU CYCLE Stats.</li><li>Update: Usage of ForEachActor methods, now returns a boolean</li></ul><h3 id="v0-6" tabindex="-1">v0.6 <a class="header-anchor" href="#v0-6" aria-label="Permalink to &quot;v0.6&quot;">​</a></h3><p><em>17/02/2024</em></p><ul><li>Add support for 5.2</li><li>Set plugin to runtime so we can use FlowPilotComponent in Blueprints</li><li>Adds FlowPilotEditor</li><li>Minor bug fixes</li></ul><h3 id="v0-5" tabindex="-1">v0.5 <a class="header-anchor" href="#v0-5" aria-label="Permalink to &quot;v0.5&quot;">​</a></h3><p><em>08/02/2024</em></p><ul><li>Removes Component from Cache</li><li>Fix Data asset sharing with instancing of assets</li><li>Sanitization pass across API calls</li><li>Adds Stats Trackers at various points</li></ul><h3 id="v0-4-1" tabindex="-1">v0.4.1 <a class="header-anchor" href="#v0-4-1" aria-label="Permalink to &quot;v0.4.1&quot;">​</a></h3><p><em>24/01/2024</em></p><ul><li>Updates validation pattern</li><li>Adds support for Unreal Engine 5.1</li></ul><h3 id="v0-4" tabindex="-1">v0.4 <a class="header-anchor" href="#v0-4" aria-label="Permalink to &quot;v0.4&quot;">​</a></h3><p><em>23/01/2024</em></p><ul><li>Added ways to Pause and Unpause FlowPilot</li><li>Added parameters to settings to configure Debug Rendering</li><li>Added proper Reset and Aborts to any Node that has Child Nodes, so they are properly propagated</li><li>Fix Parallel node wrong execution end</li><li>Fix debug rendering. Removed some options that we don&#39;t need for now and can be added later.</li><li>Simplified flow. Removed Instant nodes, they were not being used.</li><li>Added internal node state to better progress tracking</li><li>Added a way to find multiple actors from 1 external tag, so we can use group references</li><li>Added option to prefetch actors on Setup in Settings.</li><li>Inverted ChangeLog timestamps</li></ul><h3 id="v0-3-2" tabindex="-1">v0.3.2 <a class="header-anchor" href="#v0-3-2" aria-label="Permalink to &quot;v0.3.2&quot;">​</a></h3><p><em>31/12/2023</em></p><ul><li>Implement Actor Reference Tag Prefetch.</li><li>Prevent swapping FlowPilot Actor asset when Flow is already running</li><li>Allows returning Groups of Actors from an FlowActorReference via Tags. Allows Group Search, Caching and Selection</li></ul><h3 id="v0-3-1" tabindex="-1">v0.3.1 <a class="header-anchor" href="#v0-3-1" aria-label="Permalink to &quot;v0.3.1&quot;">​</a></h3><p><em>30/12/2023</em></p><ul><li>Add Retry timer to FlowPilotComponent</li><li>Properly add State change to FlowPilotComponent</li><li>Properly invalidate Database Cache in FlowPilotSubsystem when an Actor is not valid when fetching it</li></ul><h3 id="v0-3" tabindex="-1">v0.3 <a class="header-anchor" href="#v0-3" aria-label="Permalink to &quot;v0.3&quot;">​</a></h3><p><em>29/12/2023</em></p><ul><li>Fix Parallel Node not completing correctly.</li><li>Fix FlowComponent not registering correct FlowState</li></ul><h3 id="v0-1-alpha" tabindex="-1">v0.1 alpha <a class="header-anchor" href="#v0-1-alpha" aria-label="Permalink to &quot;v0.1 alpha&quot;">​</a></h3><p><em>12/12/2023</em></p><ul><li>Initial release</li></ul>',48)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
